INSERT INTO feature VALUES('shadowing-warning','diagnostics','Shadowing diagnostics','diagnostics-model','implemented','ordinary',NULL,'A declaration that shadows a builtin is warned of where it is written. The language server''s `gandr.diagnostics.shadowing` setting publishes a diagnostic at each binder that hides another binding, at the severity it names, off by default, naming the hidden binding and pointing at it.','surface-diagnostics surface-lowering surface-lsp','crates/surface-diagnostics/tests/diagnostics.rs crates/surface-lsp/src/server/fixtures/a-shadowing-binder-shows-what-it-hides-6251-importer.gandr',NULL,'#6251');
